(function() {
  var EditForm, Id, LoginForm;

  Id = {
    _id: null,
    init: function() {
      var result;
      result = /.*\/([0-9]+)\/edit\/?$/.exec(location.pathname);
      if ((result != null) && (result[1] != null)) {
        return this._id = result[1];
      }
    },
    get: function() {
      return this._id;
    }
  };

  LoginForm = {
    init: function() {
      return $("form.login").submit(function(e) {
        LoginForm.submit();
        return e.preventDefault();
      });
    },
    show: function() {
      $(".login .id").val(Id.get());
      return $("section.login").show();
    },
    hide: function() {
      return $("section.login").hide();
    },
    submit: function() {
      $('.login button').hide();
      $('.login .alert-danger').hide();
      $('.login .loader').show();
      return $.post("https://api.openwindmap.org/v1/login", $("form.login").serialize(), function(login) {
        localStorage.setItem("edit-token-" + login.id, login.token);
        LoginForm.hide();
        if (Id.get() !== login.id) {
          return document.location = "../" + login.id + "/edit";
        } else {
          return EditForm.show(login.id);
        }
      }).fail(function() {
        $('.login .alert-danger').show();
        $('.login button').show();
        return $('.login .loader').hide();
      });
    }
  };

  EditForm = {
    init: function() {
      return $("form.edit").submit(function(e) {
        EditForm.submit();
        return e.preventDefault();
      });
    },
    show: function() {
      var token;
      $('.global .loader').show();
      token = localStorage.getItem("edit-token-" + (Id.get()));
      return $.getJSON("https://api.openwindmap.org/v1/edit/" + (Id.get()) + "?token=" + token, function(data) {
        $('.edit input[name="id"]').val(data.id);
        $('.edit input[name="name"]').val(data.meta.name);
        $('.edit input[name="email"]').val(data.owner.email);
        $('.edit textarea[name="description"]').val(data.meta.description);
        $('.edit input[name="token"]').val(token);
        return $("section.settings").show();
      }).fail(function(xhr) {
        if (xhr.statusCode === 403) {
          return LoginForm.show();
        } else {
          return $('.global .alert-danger').show();
        }
      }).always(function() {
        return $('.global .loader').hide();
      });
    },
    submit: function() {
      $('.edit button').hide();
      $('.edit .alert').hide();
      $('.edit .loader').show();
      return $.post("https://api.openwindmap.org/v1/edit/" + (Id.get()), $("form.edit").serialize(), function(result) {
        if (result.ok) {
          return $('.edit .alert-success').show();
        } else {
          return $('.edit .alert-danger').show();
        }
      }).fail(function() {
        if (xhr.statusCode === 403) {
          alert("Erreur d'authentification.");
          localStorage.removeItem("edit-token-" + (Id.get()));
          return window.location.reload();
        } else {
          return $('.edit .alert-danger').show();
        }
      }).always(function() {
        $('.edit button').show();
        return $('.edit .loader').hide();
      });
    }
  };

  Id.init();

  LoginForm.init();

  EditForm.init();

  if (!localStorage.getItem("edit-token-" + (Id.get()))) {
    LoginForm.show();
  } else {
    EditForm.show();
  }

  window.logout = function() {
    localStorage.removeItem("edit-token-" + (Id.get()));
    return window.location.reload();
  };

  window.goToPioupiou = function() {
    return window.open("./../" + (Id.get()));
  };

}).call(this);

